# ==============================================================================
# 核心解碼與輸出工具函式
# ==============================================================================
function Get-Utf8String($base64) {
    if (!$base64) { return "" }
    $bytes = [System.Convert]::FromBase64String($base64)
    return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Show-Message($base64, $color) {
    if (!$base64) { return }
    $rawMsg = Get-Utf8String $base64
    $expandedMsg = $ExecutionContext.InvokeCommand.ExpandString($rawMsg)
    Write-Host $expandedMsg -ForegroundColor $color
}

function Write-Utf8File($path, $base64) {
    if (!$base64) { return }
    $bytes = [System.Convert]::FromBase64String($base64)
    [System.IO.File]::WriteAllBytes($path, $bytes)
}

if (!(Test-Path $workDir)) { 
    New-Item -ItemType Directory -Force -Path $workDir | Out-Null
    Write-Host "✅ 已建立工作目錄：$workDir" -ForegroundColor Green
}

if (!(Test-Path $scriptsDir)) { 
    New-Item -ItemType Directory -Force -Path $scriptsDir | Out-Null
